<script setup lang="ts">
import {computed,onMounted,onUnmounted,onActivated,onDeactivated,ref,shallowRef,watch,nextTick} from 'vue'
import {useStudio} from './studioContext'
import Portrait from './Portrait.vue'
import {nextMessageRequest,hintedDraft,replySegments} from './experienceRuntime'
import ExperiencePainting from './ExperiencePainting.vue'
import NarrativePlayer from './NarrativePlayer.vue'
import {prepareAssets,productionToken,reusablePresentation,type PreparedAssets} from './experienceAssets'

import {castGroups,avatarBox,messageTime,type Figure} from './experiencePresentation'
const s=useStudio(),info=ref<any>(null),view=ref<any>(null),selected=ref(''),text=ref(''),busy=ref(false),error=ref(''),stale=ref(false),pendingId=ref(''),retryText=ref(''),retryCharacter=ref('')
const shell=ref<HTMLElement>(),active=ref(true),showWaiting=ref(true),preparation=ref<any>(null),phase=ref('读取作品'),browserProgress=ref({done:0,total:0}),preparationError=ref(''),assets=shallowRef<PreparedAssets>(),contentChanged=ref(false)
let originToken='',finishing=false,submitting=false,requestId='',tickBusy=false,persistTimer:any,restoringUI=false,lastMode:'resume'|'refresh'='refresh'
const initialTitle=s.p.value?.title||'欣赏作品'
const focused=ref(''),cutouts=ref<Record<string,any>>({}),cutoutLoading=ref(false),transcript=ref<HTMLElement>(),questions=new Map<string,string>()
const playing=ref<any>(null),playbackKey=ref(0),playbackReturning=ref(false),continuous=ref(false),player=ref<InstanceType<typeof NarrativePlayer>>()
const playingIndex=computed(()=>view.value?.media.findIndex((m:any)=>m.storyboardId===playing.value?.storyboardId)??0)
function finishPlayback(){playing.value=null;focused.value='';playbackReturning.value=false}
function stepPlayback(direction:number){const next=view.value?.media[playingIndex.value+direction];if(next)playMedia(next)}
function closePlayback(){if(playing.value&&player.value)player.value.close();else finishPlayback()}
function playMedia(media:any){shell.value?.querySelectorAll('video').forEach(v=>v.pause());playing.value=media;focused.value='';playbackReturning.value=false;playbackKey.value++;s.experiments.record('media_open',{storyboardId:media.storyboardId,title:media.title,kind:media.mediaKind},'experience');void nextTick(()=>shell.value?.querySelector('.painting-viewer')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}))}
function notebookPlay(event:Event){playing.value=null;shell.value?.querySelectorAll('video').forEach(v=>{if(v!==event.target)v.pause()})}
const figures=computed<Figure[]>(()=>(view.value?.figures||view.value?.people||[]).map((v:Figure)=>({...v,canChat:v.canChat!==false})))
const cast=computed(()=>castGroups(figures.value))
const cutoutErrors=computed(()=>Object.values(cutouts.value).filter((v:any)=>v.error).map((v:any)=>({name:figures.value.find(p=>p.annotationId===v.annotationId)?.name||'人物轮廓',message:v.error})))
const autoEntering=ref(false),autoEntryId=ref('')
const completion=computed(()=>s.p.value?.workspace.jobs?.find((j:any)=>j.family==='completion'&&j.scope==='experience'))
const pid=s.p.value?.id,base=`/projects/${pid}/experience`,storageKey='animatedscroll-experience:'+pid
const categoryLabels:Record<string,string>={supported:'有依据',inference:'解释／推测',fiction:'叙事创作'}
const sourceLabels:Record<string,string>={primary:'史书原文',direct:'史书原文',indirect:'论文转引，未独立核对原书',research:'研究资料',observation:'画面观察',creator:'创作者输入'}
const segmentLabels:Record<string,string>={supported:'资料复述',inference:'已有研究推断',fiction:'合理演绎',legacy:'此回答未逐段标注'}
const usedHints=new Set<string>(),hintBackups=ref<Record<string,string>>({})
const hint=computed(()=>view.value?.session.guidance?.hint)
const person=computed(()=>figures.value.find(v=>v.annotationId===selected.value))
const turns=computed(()=>view.value?.turns.filter((t:any)=>t.characterId===person.value?.characterId)||[])
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e:any){error.value=e.message||String(e);if(e.detail?.code==='experience_stale')stale.value=true}finally{busy.value=false}}
function accept(value:any){view.value=value;if(!figures.value.some(v=>v.annotationId===selected.value))selected.value=value.people[0]?.annotationId||''}
function uiKey(sid=view.value?.session.id){return storageKey+':ui:'+sid}
function storedUI(sid:string){try{return JSON.parse(localStorage.getItem(uiKey(sid))||'{}')}catch{return {}}}
function captureUI(){if(!view.value)return;const videos:Record<string,number>={};shell.value?.querySelectorAll<HTMLVideoElement>('video[data-storyboard-id]').forEach(v=>{videos[v.dataset.storyboardId!]=v.currentTime});const state={selected:selected.value,focused:focused.value,text:text.value,questions:[...questions],scroll:active.value?(transcript.value?.scrollTop||0):(storedUI(view.value.session.id).scroll||0),windowScroll:active.value?window.scrollY:(storedUI(view.value.session.id).windowScroll||0),videos};try{localStorage.setItem(uiKey(),JSON.stringify(state))}catch{}}
function restoreUI(){if(!view.value)return;restoringUI=true;const saved=storedUI(view.value.session.id);if(figures.value.some(p=>p.annotationId===saved.selected))selected.value=saved.selected;focused.value=figures.value.some(p=>p.annotationId===saved.focused)?saved.focused:'';text.value=typeof saved.text==='string'?saved.text:'';questions.clear();for(const pair of saved.questions||[])if(Array.isArray(pair)&&pair.length===2)questions.set(pair[0],pair[1]);requestAnimationFrame(()=>{if(!active.value){restoringUI=false;return}if(transcript.value)transcript.value.scrollTop=Number(saved.scroll)||0;window.scrollTo(0,Number(saved.windowScroll)||0);shell.value?.querySelectorAll<HTMLVideoElement>('video[data-storyboard-id]').forEach(v=>{const restore=()=>{if(Number.isFinite(saved.videos?.[v.dataset.storyboardId!]))v.currentTime=saved.videos[v.dataset.storyboardId!]};if(v.readyState)restore();else v.addEventListener('loadedmetadata',restore,{once:true})});restoringUI=false})}
async function activate(value:any){
 const manifest=value.presentation;if(!manifest)throw Error('作品准备清单尚未完成')
 if(assets.value&&reusablePresentation(view.value?.presentation,manifest)){
  accept(value);originToken=productionToken(s.p.value);contentChanged.value=!!value.oldVersion;showWaiting.value=false;preparationError.value='';return
 }
 phase.value='载入图片';const loaded=await prepareAssets(manifest,(stage,done,total)=>{phase.value=stage;browserProgress.value={done,total}})
 const old={view:view.value,assets:assets.value,cutouts:cutouts.value,selected:selected.value,focused:focused.value,text:text.value}
 try{
  captureUI();assets.value=loaded;cutouts.value=Object.fromEntries(manifest.cutouts.map((v:any)=>[v.annotationId,v]));accept(value);phase.value='准备交互'
  await nextTick();await Promise.all(Array.from(shell.value?.querySelectorAll<HTMLImageElement>('.painting-plane img')||[]).map(im=>im.decode()))
  await new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve())))
  if(old.view?.session.id!==value.session.id){usedHints.clear();hintBackups.value={};pendingId.value='';retryText.value='';text.value='';questions.clear();focused.value=''}
  localStorage.setItem(storageKey,value.session.id);originToken=productionToken(s.p.value);contentChanged.value=!!value.oldVersion;showWaiting.value=false;preparationError.value='';restoreUI()
 }catch(e){view.value=old.view;assets.value=old.assets;cutouts.value=old.cutouts;selected.value=old.selected;focused.value=old.focused;text.value=old.text;throw e}
}
async function finish(job:any){if(finishing)return;finishing=true;try{phase.value='读取已准备作品';await activate(await s.api(base+'/sessions/'+job.sessionId));localStorage.removeItem(storageKey+':preparing');preparation.value=null}catch(e:any){preparationError.value=e.message}finally{finishing=false}}
async function inspectPreparation(){if(!preparation.value||tickBusy||finishing)return;tickBusy=true;try{const job=await s.api(base+'/preparations/'+preparation.value.id);preparation.value=job;phase.value=job.stage;if(job.state==='ready')await finish(job)}catch(e:any){preparationError.value='连接暂未恢复，准备成果已保留：'+e.message}finally{tickBusy=false}}
async function begin(mode:'resume'|'refresh',sid?:string){if(submitting)return;submitting=true;showWaiting.value=true;preparationError.value='';browserProgress.value={done:0,total:0};phase.value='读取作品';lastMode=mode;requestId||=crypto.randomUUID();localStorage.setItem(storageKey+':request',JSON.stringify({requestId,mode,sessionId:sid||null}));try{if(mode==='refresh')await s.saveAll();const job=await s.api(base+'/preparations','POST',{requestId,mode,sessionId:sid||null});preparation.value=job;localStorage.setItem(storageKey+':preparing',job.id);requestId='';localStorage.removeItem(storageKey+':request');phase.value=job.stage;if(job.state==='ready')await finish(job)}catch(e:any){preparationError.value=e.message}finally{submitting=false}}
async function retryPreparation(){preparationError.value='';browserProgress.value={done:0,total:0};if(!preparation.value){await begin(lastMode,view.value?.session.id||localStorage.getItem(storageKey)||undefined);return}try{preparation.value=await s.api(base+'/preparations/'+preparation.value.id+'/retry','POST',{});phase.value=preparation.value.stage}catch(e:any){preparationError.value=e.message}}
async function returnOriginal(){if(preparation.value&&['queued','running'].includes(preparation.value.state)){try{await s.api(base+'/preparations/'+preparation.value.id+'/cancel','POST',{})}catch(e:any){preparationError.value=e.message;return}}localStorage.removeItem(storageKey+':preparing');localStorage.removeItem(storageKey+':request');requestId='';preparation.value=null;preparationError.value='';showWaiting.value=false;if(!view.value)await s.navigate('characters');else restoreUI()}
async function load(){if(!pid)return;try{const sid=localStorage.getItem(storageKey),pending=localStorage.getItem(storageKey+':preparing');if(sid){try{const value=await s.api(base+'/sessions/'+sid);if(value.presentation)await activate(value);else{await begin('resume',sid);return}}catch(e:any){if(e.status===404){localStorage.removeItem(storageKey)}else throw e}}
 const request=localStorage.getItem(storageKey+':request');if(request){const saved=JSON.parse(request);requestId=saved.requestId;await begin(saved.mode,saved.sessionId||undefined);return}
 if(pending){showWaiting.value=true;preparation.value={id:pending};await inspectPreparation();return}
 if(!view.value){info.value=await s.api(base);showWaiting.value=false}
 }catch(e:any){preparationError.value=e.message;showWaiting.value=true}}
function choose(p:Figure){playing.value=null;playbackReturning.value=false;s.experiments.record('character_focus',{characterId:p.characterId,annotationId:p.annotationId,name:p.name},'experience');const current=person.value;if(current?.characterId!==p.characterId){if(current)questions.set(current.characterId,text.value);text.value=questions.get(p.characterId)||''}selected.value=p.annotationId;focused.value=p.annotationId}
function useHint(){const h=hint.value;if(!h||busy.value)return;const figure=figures.value.find(v=>v.annotationId===h.annotationId&&v.canChat);if(!figure)return;choose(figure);const draft=hintedDraft(text.value,h.question,usedHints.has(h.id));if(draft.backup!==null)hintBackups.value[h.characterId]=draft.backup;text.value=draft.text;usedHints.add(h.id)}
function restoreQuestion(){if(!person.value)return;const cid=person.value.characterId;if(cid in hintBackups.value){text.value=hintBackups.value[cid]!;delete hintBackups.value[cid]}}
async function dismissHint(){const h=hint.value;if(!h)return;await run(async()=>accept(await s.api(base+`/sessions/${view.value.session.id}/guidance/dismiss`,'POST',{hintId:h.id,requestId:'dismiss-'+h.id})))}
async function start(){if(!busy.value&&!submitting){playing.value=null;requestId='';await begin('refresh',view.value?.session.id)}}
async function send(retry=false){const target=person.value;if(!target?.canChat||!text.value.trim()||busy.value||stale.value)return;await run(async()=>{
 const message=text.value,characterId=target.characterId
 // Network retries reuse the exact request. An explicit retry of a known failed turn gets a new ID.
 pendingId.value=nextMessageRequest(pendingId.value?{requestId:pendingId.value,characterId:retryCharacter.value,text:retryText.value}:null,characterId,message,retry,()=>crypto.randomUUID()).requestId
 retryText.value=message;retryCharacter.value=characterId
 const turn=await s.api(base+`/sessions/${view.value.session.id}/messages`,'POST',{requestId:pendingId.value,characterId,text:message})
 if(turn.status==='completed'){if(person.value?.characterId===characterId&&text.value===message)text.value='';if(questions.get(characterId)===message)questions.delete(characterId);pendingId.value='';retryText.value=''}
 else if(turn.status!=='pending'){error.value=turn.message;pendingId.value=''}
 accept(await s.api(base+'/sessions/'+view.value.session.id))
})}
async function collect(turn:any,clue:any){await run(async()=>{accept(await s.api(base+`/sessions/${view.value.session.id}/collect`,'POST',{turnId:turn.id,clueId:clue.id}));const media=view.value.media.find((m:any)=>m.clueId===clue.id);if(media)playMedia(media)})}
function retry(turn:any){text.value=turn.text;void send(true)}
function scrollToLatest(){const el=transcript.value;if(el)el.scrollTo({top:el.scrollHeight,behavior:'smooth'})}
watch(()=>person.value?.characterId,()=>{if(!restoringUI&&!showWaiting.value)void nextTick(scrollToLatest)})
watch(()=>JSON.stringify(turns.value.map((t:any)=>[t.id,t.status])),()=>{if(restoringUI||showWaiting.value)return;const el=transcript.value;if(!el||el.scrollHeight-el.scrollTop-el.clientHeight<120||busy.value)void nextTick(scrollToLatest)})
watch(()=>productionToken(s.p.value),(token)=>{if(s.p.value?.id===pid&&originToken&&token!==originToken)contentChanged.value=true})
watch([text,selected,focused],()=>{clearTimeout(persistTimer);persistTimer=setTimeout(captureUI,800)})
function pause(){captureUI();playing.value=null;shell.value?.querySelectorAll('video').forEach(v=>v.pause())}
function visibility(){if(document.hidden){captureUI();shell.value?.querySelectorAll('video').forEach(v=>v.pause())}}
let timer:ReturnType<typeof setInterval>
onMounted(()=>{void load();document.addEventListener('visibilitychange',visibility);window.addEventListener('pagehide',captureUI);timer=setInterval(()=>{if(!active.value||document.hidden)return;if(showWaiting.value&&preparation.value&&['queued','running'].includes(preparation.value.state)&&!preparationError.value)void inspectPreparation();else if(!busy.value&&!stale.value&&view.value?.turns.some((t:any)=>t.status==='pending'))void run(async()=>accept(await s.api(base+'/sessions/'+view.value.session.id)))},1500)})
onActivated(()=>{active.value=true;if(view.value&&!showWaiting.value)restoreUI();if(preparation.value)void inspectPreparation()})
onDeactivated(()=>{pause();active.value=false})
onUnmounted(()=>{pause();clearTimeout(persistTimer);clearInterval(timer);document.removeEventListener('visibilitychange',visibility);window.removeEventListener('pagehide',captureUI)})
</script>
<template>
<div ref="shell" class="reader-shell" :class="{cinematic:!!playing}"><div class="reader-heading"><div><small>入画对话</small><h1>{{view?.title||initialTitle}}</h1><p>与画中人物交谈，记录线索，解锁对应分镜。</p></div><div v-if="view&&!showWaiting" class="reader-entry-actions"><button :disabled="busy" @click="start">刷新作品</button></div></div>
<p v-if="error" role="alert" class="extension-error">{{error}}</p>
<div v-if="!pid" class="empty">请先在创作工作台选择项目。</div>
<template v-else-if="!view&&!showWaiting"><div v-if="!info" class="empty" role="status">正在读取可用人物…</div><div v-else class="empty"><p v-if="!info.people.length">还没有准备好的角色。请前往人物档案生成对话设定。</p><button :disabled="busy||!info?.people.length" @click="start">开始体验</button><button v-if="!info?.people.length" @click="s.navigate('characters')">前往人物档案准备角色</button></div></template>
<template v-else-if="view">
 <div :class="{'reader-obscured':showWaiting}" :inert="showWaiting||undefined">
 <p v-if="contentChanged||view.oldVersion" class="version-notice" role="status">创作内容有更新，可刷新作品。当前体验和聊天进度保持不变。</p>
 <div class="reader-layout"><section class="reader-painting">
  <ExperiencePainting :image="view.image" :people="figures" :focused="focused" :region="!playbackReturning?(playing?.region||playing?.storyboard?.region):undefined" :cinematic="!!playing" :cutouts="cutouts" :loading="false" :assets="assets" @choose="choose" @reset="closePlayback"><Transition name="montage" mode="out-in"><NarrativePlayer v-if="playing&&!showWaiting" ref="player" :key="playbackKey" :media="playing" :image="view.image" :position="playingIndex" :total="view.media.length" :continuous="continuous" @continuous="continuous=$event" @step="stepPlayback" @return="playbackReturning=true" @close="finishPlayback"/></Transition></ExperiencePainting>

  <div class="reader-cast-heading"><span>画中人物</span><small>{{cast.length}} 位角色 · {{figures.length}} 个画中身影</small></div>
  <div class="reader-cast"><button v-for="group in cast" :key="group.person.characterId" :class="{selected:person?.characterId===group.person.characterId}" :aria-pressed="person?.characterId===group.person.characterId" @click="choose(group.instances.find(p=>p.annotationId===selected)||group.person)"><Portrait :url="view.image" :box="avatarBox(group.person)"/><span><b>{{group.person.name}}</b><small>{{group.instances.length>1?group.instances.length+' 个画中身影':group.person.canChat?'点击交谈':'尚未开放对话'}}</small></span><span v-if="person?.characterId===group.person.characterId" class="cast-active-dot"/></button></div>
 </section>
 <section class="reader-chat" v-if="person" :aria-label="'与'+person.name+'的对话'"><header class="reader-person"><Portrait :url="view.image" :box="avatarBox(person)"/><div><h2>{{person.name}}</h2><small>{{person.identity||'画中人物'}}</small></div><span class="reader-chat-status">{{person.canChat?'入画对话':'资料待完善'}}</span></header>
 <div class="reply-legend" aria-label="发言边框图例"><span class="supported">实线 · 资料复述</span><span class="inference">虚线 · 研究推断</span><span>无框 · 合理演绎</span></div>
 <div ref="transcript" class="reader-turns" role="log" aria-live="polite" aria-relevant="additions text" aria-label="对话记录"><div v-if="!turns.length" class="reader-chat-empty"><span>与 {{person.name}} 相遇</span><p>{{person.canChat?'从一句问候开始，听听画中人的故事。':(person as any).readinessReason||'这位人物还没有可用的已确认角色设定。'}}</p><small>人物身处画中当时，性格与口吻属于演绎，未知之事会坦言不知。</small></div>
  <article v-for="turn in turns" :key="turn.id" class="reader-turn">
   <div class="chat-message from-visitor"><div class="chat-message-body"><div class="chat-message-meta">你 <time>{{messageTime(turn.time)}}</time></div><div class="chat-bubble">{{turn.text}}</div></div><span class="chat-visitor-avatar" aria-hidden="true">你</span></div>
   <div class="chat-message from-character"><Portrait :url="view.image" :box="avatarBox(person)"/><div class="chat-message-body"><div class="chat-message-meta">{{person.name}} <time>{{messageTime(turn.time)}}</time></div><template v-if="turn.status==='completed'"><div v-for="(segment,index) in replySegments(turn)" :key="index" class="reply-segment" :class="segment.category"><small class="segment-label">{{segmentLabels[segment.category]}}</small><div class="chat-bubble">{{segment.text}}</div><details v-if="segment.evidence.length" class="segment-evidence"><summary>查看本段依据与来源身份</summary><div v-for="basis in segment.evidence" :key="basis.basisId"><p>{{basis.text}}</p><blockquote v-for="(source,i) in basis.sources" :key="i"><q>{{source.quote}}</q><small>{{source.title||source.sourceTitle||source.sourceId}} · {{sourceLabels[source.level]||'已确认资料'}}</small><small v-if="source.edition">版本与出处：{{source.edition}}</small><small v-if="source.locator||source.page">定位：{{source.locator||('第'+source.page+'页')}}</small><small v-if="source.verification==='unverified'">尚未独立核对原书版本</small><small v-if="source.indirectSource">经文献转引：{{source.indirectSource}}；未独立核对原书</small></blockquote></div></details></div></template><div v-else class="chat-bubble" :class="{'chat-failed':turn.status!=='pending'}" role="status"><span v-if="turn.status==='pending'" class="chat-typing"><i/><i/><i/></span>{{turn.message||(turn.status==='pending'?'正在思考…':'回答未完成')}}<button v-if="['failed','interrupted'].includes(turn.status)" :disabled="busy||stale" @click="retry(turn)">重新发送</button></div></div></div>
   <div v-if="turn.clues?.length" class="chat-discoveries"><div v-for="clue in turn.clues" :key="clue.id" class="chat-discovery"><div><small>谈话中的线索 · {{clue.categories.map((c:string)=>(categoryLabels[c]||c)).join('、')}}</small><b>{{clue.name}}</b></div><button :disabled="busy||stale" @click="collect(turn,clue)">{{view.session.collectedClueIds.includes(clue.id)?'✓ 已记录 · 重播讲解':'＋ 记录线索'}}</button><details v-if="clue.evidence.length"><summary>展开原文依据</summary><blockquote v-for="(e,index) in clue.evidence" :key="index"><p>{{e.quote}}</p><cite>{{e.title}}</cite></blockquote></details></div></div>
  </article>
 </div>
 <aside v-if="hint" class="reader-hint" aria-label="线索话题引导"><div><small>换个话题</small><button class="hint-close" :disabled="busy" @click="dismissHint" aria-label="关闭线索引导">×</button><p>可以问问{{hint.name}}：{{hint.topic}}</p><p class="hint-question">“{{hint.question}}”</p></div><button :disabled="busy" @click="useHint">找{{hint.name}}聊聊 · 填入问题</button><small>选人并填入问题，点击发送后才交谈。</small></aside>
 <form class="reader-composer" @submit.prevent="send()"><label for="reader-question">向{{person.name}}提问</label><textarea id="reader-question" v-model="text" maxlength="2000" rows="3" :disabled="busy||stale||!person.canChat" :placeholder="person.canChat?'点击此处输入问题…':'此人物的知识尚未开放'"/><button v-if="person.characterId in hintBackups" type="button" class="restore-question" @click="restoreQuestion">恢复引导前的未发送问题</button><div class="reader-composer-footer"><small>{{text.length?text.length+' / 2000':person.canChat?'输入问题后，点击发送即可交谈':'请在人物档案补充对话设定后开始体验'}}</small><button class="primary" :disabled="busy||stale||!person.canChat||!text.trim()">{{busy?'发送中…':'发送 ↑'}}</button></div></form></section></div>
 <section class="reader-notebook"><h2>线索手记与已解锁分镜</h2><p v-if="!view.session.collectedClueIds.length" class="muted">读到回答后，点击记录线索。</p><p v-else>已收集 {{view.session.collectedClueIds.length}} 条线索。</p><details v-for="clue in view.collectedClues||[]" :key="clue.id" class="reader-clue"><summary>{{clue.name}} · {{clue.categories.map((c:string)=>categoryLabels[c]||c).join('、')}}</summary><p>{{clue.text}}</p><p v-for="e in clue.evidence"><q>{{e.quote}}</q><small>{{e.title}}</small></p></details><div class="reader-filmstrip" aria-label="已解锁分镜"><button v-for="(media,i) in view.media" :key="media.storyboardId" :class="{active:playing?.storyboardId===media.storyboardId}" :aria-label="'进入分镜：'+media.title" :aria-pressed="playing?.storyboardId===media.storyboardId" @click="playMedia(media)"><div class="filmstrip-image"><Portrait :url="view.image" :box="media.region||media.storyboard?.region||{x:0,y:0,w:1,h:1}"/><span>▷</span><small>{{String(Number(i)+1).padStart(2,'0')}}</small></div><b>{{media.title}}</b><small>{{media.videoUrl?'分镜视频':media.imageUrl?'分镜图像':'原画叙事 · 非生成视频'}}</small></button></div></section>
 </div>
</template>
<section v-if="showWaiting" class="experience-wait" aria-label="作品准备" aria-live="polite"><div class="experience-wait-card"><div v-if="!preparationError&&!['failed','interrupted','cancelled'].includes(preparation?.state)" class="experience-spinner"/><h2>{{preparationError||['failed','interrupted','cancelled'].includes(preparation?.state)?'作品还未准备完成':'正在准备作品'}}</h2><p role="status">{{phase}}</p><progress v-if="(browserProgress.total||preparation?.total)>0" :value="browserProgress.total?browserProgress.done:Math.max(0,preparation.completed-(preparation.errors?.length||0))" :max="browserProgress.total||preparation.total"/><small v-if="preparation?.total">人物已就绪 {{Math.max(0,(preparation.completed||0)-(preparation.errors?.length||0))}} / {{preparation.total}} · {{preparation.current||''}}</small><p v-if="preparationError" role="alert">{{preparationError}}</p><p v-for="(item,i) in preparation?.errors||[]" :key="i" class="preparation-issue">{{item.name||figures.find(p=>p.annotationId===item.annotationId)?.name||'准备项目'}}：{{item.message}}</p><div class="actions"><button v-if="preparationError||['failed','interrupted','cancelled'].includes(preparation?.state)" @click="retryPreparation">重试未完成项</button><button v-if="preparationError&&!view" @click="start">刷新作品</button><button v-if="view" @click="returnOriginal">返回原体验</button><button v-else @click="returnOriginal">返回创作</button></div><small>全部准备好后再进入体验；已完成资源会保留。</small></div></section>
</div>
